# -*- coding: utf-8 -*-
# Рядок 404: еталон 60 речей проти ПОТОЧНОГО каталогу, «поле × джерело», п/х/м/в/нс = правильно/хибно/мовчання (невідомо, нема поля)/
# вигадано/не судиться. (а) текст крамниці (записав суддя), (б) продукт сьогодні, (в) фото qwen3-vl, (г) розбір MamayLM, (д) що дав би
# `_ЗАМІНЕНІ_РОЗБОРОМ` (г там, де є, інакше б), (е) г лише там, де текст має опору (верхня межа сторожа цитат РЗ-К).
# Запуск: python3 проби/еталон_поточний.py [розбір.json]  (без аргументу — з гілки claude/rz1-rozbir-zlyttia; ~1.5 хв)
import sys, os, ast, json, subprocess, collections as C
ТУТ = os.path.dirname(os.path.abspath(__file__)); Д = os.path.dirname(ТУТ); sys.path.insert(0, Д); os.chdir(Д)
import feed as F; F.каталог_на_диску('каталог_повний.xml')
import фід_каталог as ФК, каталог_розбір as КР, внутрішня_мова as ВМ, verify as V; Е = json.load(open(ТУТ + '/еталон_розбору.json', encoding='utf-8')); ПОЛЯ = Е['поля']
ПОЛЯ_Б = ('слот', 'тип', 'набір', 'довжина_рівень', 'довжина_джерело', 'рукав_слово', 'крій', 'крій_джерело', 'волокно', 'волокно_джерело', 'матеріал', 'матеріал_фото',
          'візерунок', 'візерунок_джерело', 'колір_назва', 'колір_назва_джерело', 'колір_назва_фото', 'колір_джерело', 'блиск', 'блиск_джерело', 'метал', 'деталі_крою')
for файл in (ТУТ + '/еталон_частки.py', ТУТ + '/../../аудит/проби/еталон_збірка.py'):   # ті самі суд і зведення до кодів, що збирали еталон
    дерево = ast.parse(open(файл, encoding='utf-8').read())
    exec(compile(ast.Module([в for в in дерево.body if isinstance(в, ast.FunctionDef) or 'НАЗАД' in ast.dump(в)[:60] or 'ДОВЖИНА' in ast.dump(в)[:60]], []), файл, 'exec'))
розбір = json.load(open(sys.argv[1], encoding='utf-8')) if len(sys.argv) > 1 else json.loads(subprocess.check_output(['git', '-c', 'core.quotepath=off', 'show',
    'origin/claude/rz1-rozbir-zlyttia:аудит/розбір_каталогу/mamaylm-gemma-3-12b-it-v2.0_uk_povnyi/розбір.json'], cwd=Д))
кат = {x['id']: x for x in ФК._прочитати_каталог('каталог_повний.xml', 0)['каталог']}; оф = {o['id']: o for o in F.читати_yml('каталог_повний.xml')[0]}; зб = F.читати_збагачення()
МАПА = ('item_type', 'cut', 'fabric', 'length', 'sleeve', 'pattern')   # поля коду, які в короткому записі заміняє розбір
КЛ = {'правильно': 'п', 'хибно': 'х', 'вигадано': 'в', 'невідомо': 'м', 'нема поля': 'м', 'не судиться': 'нс'}
рах, за_групою, нема, зсув = C.defaultdict(C.Counter), C.defaultdict(C.Counter), [], C.Counter()
for р in Е['речі']:
    x, взуття = кат.get(р['id']), 'shoes' in р['правда']['slot']
    if x is None or р['id'] not in розбір: нема.append(р['id']); continue
    б, тб = продукт(dict(б={к: x.get(к) for к in ПОЛЯ_Б}, б_словники=КР.що_каже_код(оф[р['id']])[0]), взуття); г = з_розбору(розбір[р['id']], взуття)
    знає = {п: п in МАПА and г[п] not in (None, 'unknown', []) for п in ПОЛЯ}
    дж = dict(а=(р['джерела']['а'], {}), б=(б, тб), в=(збагачення(зб.get(р['id']), взуття), {}), г=(г, {}), д=({п: г[п] if знає[п] else б[п] for п in ПОЛЯ}, {п: знає[п] or тб[п] for п in ПОЛЯ}),
              е=({п: г[п] if р['опора'].get(п) else None for п in ПОЛЯ}, {}))
    for ім, (к, текст) in дж.items():
        for п in ПОЛЯ:
            в = 'нема поля' if к[п] == 'нема поля' else суд(р['правда'][п], р['опора'].get(п, []), к[п], ім in 'ге' or текст.get(п, False))
            рах[ім, п][КЛ[в]] += 1; рах[ім, '*'][КЛ[в]] += 1; за_групою[ім, р['група']][КЛ[в]] += 1
            if ім in 'бд' and п in МАПА: зсув[ім, в] += 1
    зсув['дрейф'] += sum(суд(р['правда'][п], р['опора'].get(п, []), б[п], тб[п]) != р['вердикти']['б'][п] for п in ПОЛЯ if б[п] != 'нема поля')
print('речей в еталоні %d, у поточному каталозі й розборі %d; зникло: %s' % (len(Е['речі']), len(Е['речі']) - len(нема), нема or 'нема'), '\n' + '%-10s' % 'поле' + ''.join('%-17s' % ('(%s) п/х/м/в/нс' % і) for і in 'абвгде'))
for п in ПОЛЯ + ['*']: print('%-10s' % (п if п != '*' else 'УСЕ') + ''.join('%-17s' % '/'.join(str(рах[і, п][к]) for к in ('п', 'х', 'м', 'в', 'нс')) for і in 'абвгде'))
for і in 'абвгде':
    с = рах[і, '*']; з = max(1, с['п'] + с['х'] + с['в']); print('(%s) поставлено %d: правильно %.0f%%, хибно %.0f%%, вигадано %.0f%% · вигадок на 720 полів %.1f%% · у 20 мовчазних речей вигадано %d з 240' % (
        і, з, 100 * с['п'] / з, 100 * с['х'] / з, 100 * с['в'] / з, 100 * с['в'] / 720, за_групою[і, 'мовчазна']['в']))
print('6 полів заміни (б → д): правильно %d → %d, хибно %d → %d, вигадано %d → %d, мовчання %d → %d; вердиктів (б) змінилось з 01.10: %d' % (
    *[v for к in ('правильно', 'хибно', 'вигадано', 'невідомо') for v in (зсув['б', к], зсув['д', к])], зсув['дрейф']))
